// One scripted round per sendMessage call, to drive the tool loop round by round.
const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (response: ToolResponse): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => response
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const chunksFrom = async (stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> => {
  const chunks: MessageChunk[] = [];
  for await (const chunk of stream) chunks.push(chunk);
  return chunks;
};

describe('ChatOrchestrator tool loop', () => {
  it('runs another round after a tool call and streams both rounds in order', async () => {
    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'the answer'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'text', 'stop']);
  });

  it('stops after one round when nothing asked for a tool', async () => {
    const provider = scriptedProvider([[{type: 'text', text: 'done'}, STOP_DONE], [{type: 'text', text: 'never'}]]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'x'}));

    const text = await orchestrator.processMessage(createSession('ask'));

    expect(text).toBe('done');
  });

  it('stops asking for tools once maxToolRounds is spent', async () => {
    const alwaysTools = Array.from({length: 10}, () => [TOOL_CALL, STOP_FOR_TOOL]);
    const orchestrator = createChatOrchestrator(
      scriptedProvider(alwaysTools),
      promptBuilder,
      registryReturning({result: 'again'}),
      {maxToolRounds: 2}
    );

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.filter(c => c.type === 'tool_use')).toHaveLength(3);
  });

  it('forwards the client messages a tool returned as one tool_result chunk', async () => {
    const forwarded: OutgoingMessage = {type: 'entry_commit', index: 7};
    const orchestrator = createChatOrchestrator(
      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
      promptBuilder,
      registryReturning({result: 'r', clientMessages: [forwarded]})
    );

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks).toContainEqual({type: 'tool_result', clientMessages: [forwarded]});
  });

  it('appends an upserted entry to the session and rewrites its index to match', async () => {
    const entry: SessionEntry = {role: 'assistant', content: 'from the tool', timestamp: SENT_AT, isStreaming: false};
    const orchestrator = createChatOrchestrator(
      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
      promptBuilder,
      registryReturning({result: 'r', clientMessages: [{type: 'entry_upsert', index: 999, entry}]})
    );
    const session = createSession('ask');

    const chunks = await chunksFrom(orchestrator.processMessageStream(session));

    expect(chunks).toContainEqual({
      type: 'tool_result',
      clientMessages: [{type: 'entry_upsert', index: session.entries.length - 1, entry}],
    });
  });

  it('asks for suppression when the tool says the reply is already handled', async () => {
    const orchestrator = createChatOrchestrator(
      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
      promptBuilder,
      registryReturning({result: 'r', suppressAssistantResponse: true})
    );

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'suppress_output', 'stop']);
  });

  it('joins the text of every round, not only the last', async () => {
    let seen = '';
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, responseText) => {
        seen = responseText;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [{type: 'text', text: 'first '}, TOOL_CALL, STOP_FOR_TOOL],
        [{type: 'text', text: 'second'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toBe('first second');
  });

  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });
});

--- workflow test command ---
name: CI

on:
  pull_request:
  push:
    branches: [main]
  # Manual runs: re-checking a branch against a moved main, or confirming a gate after
  # changing one, without pushing an empty commit.
  workflow_dispatch:
  # An advisory published after a merge is invisible until someone opens a pull request, and this
  # repository can go days without one. Monday 07:00 UTC; only `build-chain` answers it.
  schedule:
    - cron: '0 7 * * 1'

# Every job here only reads the checkout; the repo default is write.
permissions:
  contents: read

# A newer push to the same branch supersedes an in-flight run. main is exempt:
# every commit there should have its own recorded result.
concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: ${{ github.ref != 'refs/heads/main' }}

jobs:
  verify:
    name: Verify
    # The scheduled run exists for the dependency audit; re-running the suite on an unchanged
    # tree every Monday would report nothing new.
    if: github.event_name != 'schedule'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
          # Full history, not for this job but for the spec anchor check below:
          # it resolves cited content from
          # origin/main, which a shallow clone cannot serve.
          fetch-depth: 0

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          cache: npm

      # --ignore-scripts so `prepare` does not build on install: what a lifecycle script
      # runs is out of this workflow's control, and the Build step below is where a broken
      # compile should be reported. Type check catches it earlier still.
      - name: Install
        run: npm ci --ignore-scripts

      # Every `npm run` step below is one link of the `verify` script in
      # package.json, in the same order - scripts/verify-script.test.ts holds
      # the two together - and kept as separate steps so a red run names the
      # gate that failed rather than a single opaque command.
      - name: Type check
        run: npm run typecheck

      # example/ is outside tsconfig.json's rootDir, so nothing checked the one
      # file the README and the guide are written against.
      - name: Type check the example
        run: npm run typecheck:example

      - name: Lint (--max-warnings 0)
        run: npm run eslint

      # Reports, never blocks. The one rule it runs is `warn`, so the step exits
      # 0 on its own and carries no continue-on-error: a non-zero exit here now
      # means the config itself broke, and that should fail. Its findings render
      # as warning annotations rather than failures, which is what a report on a
      # passing check should look like.
      #
      # require-statement-links counts spec statements with no test behind them.
      # Most of what it reports needs a test written rather than a line changed,
      # so the count is meant to be visible on every run and to fall over time.
      # Its test-side mirror, require-spec-link, is satisfied and gates in the
      # Lint step above. Never add a rule here to escape a red gate -
      # eslint.config.backlog.mjs says what belongs.
      - name: Spec traceability backlog (report)
        run: npm run lint:backlog

      - name: Format check
        run: npm run prettier:check

      # Runs the whole suite and fails it on the committed coverage floor in
      # jest.config.js, so this is the test gate rather than an extra pass.
      - name: Test (with coverage floor)
        run: npm run test:coverage

      - name: Build
        run: npm run build

      # Anchors drift silently: a cited file gaining or losing lines above the
      # cited one leaves the link pointing at different content, and the spec
      # still reads as cited. Resolves content at origin/main, which the
      # fetch-depth: 0 above exists to provide. A red check is fixed by running
      # `node scripts/repoint-spec-anchors.mjs` and committing the result.
      - name: Spec anchor check
        run: node scripts/repoint-spec-anchors.mjs --check origin/main

      # A citation counts as coverage only in its statement's trailing
      # parenthetical; one written mid-statement is dropped by the Lore job in silence,
      # so the spec reads as cited while its coverage is zero. A red check is
      # fixed by moving the link to the end of its statement, never by deleting
      # it (AGENTS.md § Spec Test Links).
      # Every fenced typescript block in the three documented files is generated
      # from source; hand transcription is what produced the defects this catches.
      - name: Documented code blocks
        run: npm run docs:check

      # Three rules that held only because somebody remembered them: a path in prose that resolves,
      # a spike that says it is a spike, and an example region inside the EU.
      - name: Documented paths resolve
        run: npm run docs:check-paths

      - name: Spike documents carry a status block
        run: npm run docs:check-spikes

      - name: Documented regions
        run: npm run check:regions

      # A line number is a derived pointer; the name is what the author cited. This catches a citation
      # whose line moved under it, which no baseline comparison can see on a branch that edits the spec.
      - name: Spec citations name their test
        run: npm run spec:names

      - name: Spec link placement
        run: npm run check:spec-links

      # Lead paragraphs and a spec's status-vs-coverage are ESLint's job; the
      # one verdict a `files` glob cannot express - that an ADR's frontmatter
      # status parses, without holding the ADR to the coverage tier - is this
      # script's. `check:spec-status -- --coverage` lists unlinked statements
      # and never gates.
      - name: Spec status
        run: npm run check:spec-status

      # A release note and a commit subject have different readers, so this is a
      # file the author writes rather than something derived from the log. The
      # label is the escape hatch for a src/ change nothing installable observes.
      - name: Changelog entry
        if: github.event_name == 'pull_request' && !contains(github.event.pull_request.labels.*.name, 'no-changelog')
        # No fetch: the checkout above resolves every head into refs/remotes
        # with fetch-depth 0, and its credential is gone by the time a step
        # runs, so fetching here asked an unauthenticated git for a private
        # repository and exited 128 before the gate was ever reached.
        run: bash scripts/check-changelog.sh "origin/${{ github.base_ref }}"

  # Separate job, not a step on `verify`: these two check what the build chain
  # pulls in rather than what the code does, and a red audit should not read as
  # a failing test suite. It needs the tree installed but nothing built, so it
  # skips `prepare` with --ignore-scripts.
  build-chain:
    name: Build chain
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          cache: npm

      - name: Install (no build)
        run: npm ci --ignore-scripts

      # Full tree, dev included: those packages are what a runner installs
      # before building dist/, and the release workflow signs what it produces.
      - name: Audit (high and above)
        run: npm run check:audit

      # A tag is a mutable pointer its owner can repoint under a job that holds
      # repository credentials.
      - name: Action pins
        run: npm run check:action-pins

  # Its own job because it is the only check that exercises the package as a
  # consumer receives it - packed, installed outside this tree, with no optional
  # peer present. Everything else here tests the source in place, where every
  # dependency is already installed and every one of these failures is invisible.
  smoke:
    name: Smoke (packed tarball)
    if: github.event_name != 'schedule'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          cache: npm

      - name: Install (no build)
        run: npm ci --ignore-scripts

      # Explicit, rather than relying on `npm pack` to trigger `prepare`: a build failure should be
      # reported by a step named Build, not as a confusing pack error inside the smoke script.
      - name: Build
        run: npm run build

      # Two variants, two jobs' worth of signal in one: `bare` is a mock-provider consumer with no
      # optional peer, `full` is a Bedrock or Vertex consumer with both. They fail differently and
      # separate steps name which consumer is broken.
      - name: Smoke (no optional peer)
        run: npm run smoke -- bare

      - name: Smoke (both optional peers)
        run: npm run smoke -- full

import type {ChatSession} from '../types/session.js';
import type {ToolRegistry, ToolContext} from './tools/registry.js';
import type {
  AIProvider,
  Message,
  MessageChunk,
  SendMessageParams,
  ToolCall,
  ToolResultContent,
  UsageMetadata,
} from '../types/ai.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
import {toMessages, createContextConfig} from './conversationContext.js';
import type {ContextConfig} from './conversationContext.js';
import {
  shouldContinueToolLoop,
  collectText,
  buildToolCallMessages,
  collectToolCalls,
  extractStopReason,
  extractUsage,
} from './orchestratorHelpers.js';
import {appendEntry} from './entryMutations.js';
import {log} from '../shared/logger.js';

const DEFAULT_MAX_TOOL_ROUNDS = 5;

export interface OrchestratorHooks {
  beforeSession?: (session: ChatSession) => Promise<void>;
  afterSession?: (session: ChatSession) => Promise<void>;
  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
  onError?: (session: ChatSession, error: Error) => Promise<void>;
}

export interface ChatOrchestrator {
  processMessage(session: ChatSession): Promise<string>;
  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
}

export interface ChatOrchestratorOptions {
  maxToolRounds?: number;
  contextConfig?: Partial<ContextConfig>;
  promptBuilderOptions?: PromptBuilderOptions;
  hooks?: OrchestratorHooks;
}

interface ToolExecutionResult {
  clientMessages: OutgoingMessage[];
  suppressOutput: boolean;
}
export function createChatOrchestrator(
  provider: AIProvider,
  promptBuilder: PromptBuilder,
  toolRegistry?: ToolRegistry,
  options?: ChatOrchestratorOptions
): ChatOrchestrator {
  const maxToolRounds = options?.maxToolRounds ?? DEFAULT_MAX_TOOL_ROUNDS;
  const contextConfig = createContextConfig(options?.contextConfig);
  const toolInstructions = toolRegistry?.getPromptInstructions();
  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
  const tools = toolRegistry?.getDefinitions();
  const hooks = options?.hooks;

  return {
    async processMessage(session: ChatSession): Promise<string> {
      return collectText(this.processMessageStream(session));
    },

    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
      if (hooks?.beforeSession) await hooks.beforeSession(session);

      try {
        let userMessage = lastUserContent(session);

        if (hooks?.beforeUserInput) {
          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
        }

        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);

        const systemPrompt = hooks?.beforeModelResponse
          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
          : baseSystemPrompt;

        const messages: Message[] = toMessages(session.entries, contextConfig);
        let lastUsage: UsageMetadata | undefined;
        let responseText = '';

        for (let round = 0; round <= maxToolRounds; round++) {
          log.info('orchestrator', 'starting round', {round});
          const pendingToolCalls: ToolCall[] = [];

          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
          responseText += outcome.text;
          lastUsage = outcome.usage ?? lastUsage;

          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;

          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
          const {clientMessages, suppressOutput} = await executeToolCalls(
            pendingToolCalls,
            messages,
            toolRegistry!,
            session
          );
          log.info('orchestrator', 'tool execution complete', {
            clientMessageCount: clientMessages.length,
            clientMessageTypes: clientMessages.map(m => m.type),
            suppressOutput,
          });

          if (clientMessages.length > 0) {
            yield {type: 'tool_result' as const, clientMessages};
          }

          if (suppressOutput) {
            yield {type: 'suppress_output' as const};
          }
        }

        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
      } catch (error) {
        if (hooks?.onError && error instanceof Error) {
          await hooks.onError(session, error);
        }
        throw error;
      } finally {
        if (hooks?.afterSession) await hooks.afterSession(session);
      }
    },
  };
}

interface RoundOutcome {
  stopReason: string;
  text: string;
  usage?: UsageMetadata;
}

// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
async function* streamRound(
  provider: AIProvider,
  request: SendMessageParams,
  pendingToolCalls: ToolCall[]
): AsyncGenerator<MessageChunk, RoundOutcome> {
  let stopReason = '';
  let text = '';
  let usage: UsageMetadata | undefined;

  for await (const chunk of provider.sendMessage(request)) {
    yield chunk;
    collectToolCalls(chunk, pendingToolCalls);
    stopReason = extractStopReason(chunk) ?? stopReason;
    usage = extractUsage(chunk) ?? usage;
    if (chunk.type === 'text') text += chunk.text;
  }

  return {stopReason, text, usage};
}

// A changed message is also written back to the session's last user entry.
async function rewriteUserMessage(
  session: ChatSession,
  userMessage: string,
  hook: (session: ChatSession, userMessage: string) => Promise<string>
): Promise<string> {
  const modified = await hook(session, userMessage);
  if (modified === userMessage) return userMessage;

  updateLastUserContent(session, modified);
  return modified;
}

function lastUserContent(session: ChatSession): string {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') return entry.content;
  }
  return '';
}

function updateLastUserContent(session: ChatSession, content: string): void {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') {
      entry.content = content;
      return;
    }
  }
}

async function executeToolCalls(
  pendingToolCalls: ToolCall[],
  messages: Message[],
  toolRegistry: ToolRegistry,
  session: ChatSession
): Promise<ToolExecutionResult> {
  messages.push(buildToolCallMessages(pendingToolCalls));

  const context: ToolContext = {
    userId: session.userId,
    sessionId: session.sessionId,
    workspaceId: session.workspaceId,
    authHeaders: session.authHeaders,
  };

  const responses = await Promise.all(
    pendingToolCalls.map(async tc => {
      const response = await toolRegistry.execute(tc.name, tc.input, context);
      return {tc, response};
    })
  );

  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
    type: 'tool_result' as const,
    toolUseId: tc.id,
    content: response.result,
  }));
  messages.push({role: 'user', content: toolResults});

  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);

  return {
    clientMessages: assignEntryIndices(rawClientMessages, session),
    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
  };
}

function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
  return clientMessages.map(msg => {
    if (msg.type !== 'entry_upsert') return msg;
    const index = appendEntry(session, msg.entry);
    return {...msg, index};
  });
}
import type {OutgoingMessage} from './messages.js';

